/*
* Safeguarding test for requirement "polar-coordinate-clipping":
* fix(polar): fix unexpected clipping in polar coordinate (apache/echarts#20370)
*
* Polar.getArea().contain() previously subtracted the epsilon from d2 only,
* which wrongly excluded points at the inner radius (notably the center point
* when r0 === 0) and had no explicit guard for the degenerate r === r0 ring.
*/

import { createChart, removeChart } from '../test/ut/core/utHelper';
import { EChartsType } from '../src/echarts';
import type Polar from '../src/coord/polar/Polar';

describe('polar-coordinate-clipping', function () {

    let chart: EChartsType;

    afterEach(function () {
        if (chart) {
            removeChart(chart);
            chart = null;
        }
    });

    function getPolarArea() {
        chart = createChart();
        chart.setOption({
            polar: {},
            angleAxis: {
                type: 'category',
                data: ['a', 'b', 'c']
            },
            radiusAxis: {
                max: 100
            },
            series: [{
                type: 'scatter',
                coordinateSystem: 'polar',
                data: [[0, 100], [1, 0], [2, 50]]
            }]
        });
        const seriesModel = chart.getModel().getSeriesByIndex(0);
        const polar = (seriesModel as unknown as { coordinateSystem: Polar }).coordinateSystem;
        return polar.getArea();
    }

    it('contains the point at the max radius (edge must not be clipped)', function () {
        const area = getPolarArea();
        const polar = (chart.getModel().getSeriesByIndex(0) as unknown as { coordinateSystem: Polar })
            .coordinateSystem;
        const point = polar.dataToPoint([0, 100]);
        expect(area.contain(point[0], point[1])).toBe(true);
    });

    it('contains the center point when r0 is 0', function () {
        const area = getPolarArea();
        const polar = (chart.getModel().getSeriesByIndex(0) as unknown as { coordinateSystem: Polar })
            .coordinateSystem;
        const point = polar.dataToPoint([1, 0]);
        expect(area.contain(point[0], point[1])).toBe(true);
    });

    it('still excludes points outside the ring (legitimate clipping)', function () {
        const area = getPolarArea();
        const polar = (chart.getModel().getSeriesByIndex(0) as unknown as { coordinateSystem: Polar })
            .coordinateSystem;
        const outside = polar.dataToPoint([2, 200]);
        expect(area.contain(outside[0], outside[1])).toBe(false);
        // A point clearly beyond the outer radius in raw pixels.
        expect(area.contain(area.cx + area.r + 10, area.cy)).toBe(false);
    });

    it('contains nothing when r equals r0 (degenerate ring)', function () {
        chart = createChart();
        chart.setOption({
            polar: {},
            angleAxis: {
                type: 'category',
                data: ['a', 'b', 'c']
            },
            radiusAxis: {
                min: 100,
                max: 100
            },
            series: [{
                type: 'scatter',
                coordinateSystem: 'polar',
                data: [[0, 100]]
            }]
        });
        const polar = (chart.getModel().getSeriesByIndex(0) as unknown as { coordinateSystem: Polar })
            .coordinateSystem;
        const area = polar.getArea();
        const point = polar.dataToPoint([0, 100]);
        expect(area.contain(point[0], point[1])).toBe(false);
    });
});

